Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
#define cs const
#define pb push_back
using namespace std;
int Mod; 
int add(int a, int b){ return a + b >= Mod ? a + b - Mod : a + b; }
int dec(int a, int b){ return a - b < 0 ? a - b + Mod : a - b; }
int mul(int a, int b){ return 1ll * a * b % Mod; }
void Add(int &a, int b){ a = add(a, b); }
void Dec(int &a, int b){ a = dec(a, b); }
void Mul(int &a, int b){ a = mul(a, b); }
cs int N = 1e3 + 50;
int n, m, f[N], g[N];
int C[N][N];
void fc_init(int n){
	for(int i = 0; i <= n; i++) C[i][0] = 1; 
	for(int i = 1; i <= n; i++)
	for(int j = 1; j <= i; j++)
	C[i][j] = add(C[i - 1][j - 1], C[i - 1][j]);
}
int main(){
	#ifdef FSYo
	freopen("1.in", "r", stdin);
	#endif
	cin >> n >> m >> Mod;
	f[1] = 2, g[1] = 0;
	fc_init(max(m, n - m + 1));
	for(int i = 2; i <= m; i++){
		f[i] = mul(f[i - 1], 2 * (i + 1));
		g[i] = mul(g[i - 1], 2 * (i + 1));
		Add(g[i], mul(f[i - 1], i * (i - 1)));
		for(int j = 1; j < i; j++){
			int k = i - j - 1;
			int c = mul(C[j + k][j], j + k + 2);
			Add(f[i], mul(c, mul(f[j], f[k])));
			Add(g[i], mul(c, mul(f[j], g[k])));
			Add(g[i], mul(c, mul(g[j], f[k])));
			int w = j * (j + 1) / 2 + k * (k + 1) / 2;
			Add(g[i], mul(mul(C[j + k][j], w), mul(f[j], f[k])));
		} 
	}
	static int dp[N][N][2];
	dp[0][0][0] = 1; 
	for(int i = 0; i <= m; i++)
	for(int j = 0; j <= m; j++)
	for(int o = 0, c; o < 2; o++)
	if(c = dp[i][j][o]){
		if(!o)
		for(int k = 1; k + j <= m; k++)
		Add(dp[i + 1][j + k][0], mul(mul(c, C[j + k][k]), f[k])), 
		Add(dp[i + 1][j + k][1], mul(mul(c, C[j + k][k]), g[k]));
		else 
		for(int k = 1; k + j <= m; k++)
		Add(dp[i + 1][j + k][1], mul(mul(c, C[j + k][k]), f[k]));
	} 
	int ans = 0;
	for(int i = 1; i <= m; i++)
	Add(ans, mul(dp[i][m][1], C[n - m + 1][i]));
	cout << ans; 
	return 0;
}
